import unittest

def is_palindrome(s):
    return s == s[::-1]

class TestIsPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(is_palindrome(""))

    def test_single_character(self):
        self.assertTrue(is_palindrome("a"))

    def test_two_characters_palindrome(self):
        self.assertTrue(is_palindrome("aa"))

    def test_two_characters_not_palindrome(self):
        self.assertFalse(is_palindrome("ab"))

    def test_odd_length_palindrome(self):
        self.assertTrue(is_palindrome("aba"))

    def test_even_length_palindrome(self):
        self.assertTrue(is_palindrome("abba"))

    def test_odd_length_not_palindrome(self):
        self.assertFalse(is_palindrome("abc"))

    def test_even_length_not_palindrome(self):
        self.assertFalse(is_palindrome("abcd"))

    def test_mixed_case(self):
        # Note: The current implementation is case-sensitive
        self.assertFalse(is_palindrome("Abba"))
        self.assertTrue(is_palindrome("Abba".lower()))

    def test_with_spaces(self):
        # Note: The current implementation considers spaces
        self.assertFalse(is_palindrome("a b"))
        self.assertTrue(is_palindrome("aba"))

    def test_numbers(self):
        self.assertTrue(is_palindrome("121"))
        self.assertFalse(is_palindrome("123"))

if __name__ == '__main__':
    unittest.main()
